use aspis_core::{field::{M31,CM31,QM31,WideExact,P},r0::CodeField};
fn q(s:u32)->QM31 {QM31{c0:CM31::new(M31(s),M31(s.wrapping_mul(17))),c1:CM31::new(M31(s.rotate_left(7)),M31(s.rotate_right(3)))}}
fn mi(x:M31)->Option<M31>{if x==M31::ZERO {None}else{Some(x.pow(u64::from(P-2)))}}
fn ci(x:CM31)->Option<CM31>{let n=x.a.mul(x.a).add(x.b.mul(x.b));let i=mi(n)?;Some(CM31::new(x.a.mul(i),x.b.neg().mul(i)))}
fn qi(x:QM31)->Option<QM31>{let r=CM31::new(M31(2),M31::ONE);let n=x.c0.mul(x.c0).sub(r.mul(x.c1.mul(x.c1)));let i=ci(n)?;Some(QM31{c0:x.c0.mul(i),c1:x.c1.neg().mul(i)})}
fn wi(x:WideExact)->Option<WideExact>{let n=x.c0().mul(x.c0()).sub(WideExact::U.mul(x.c1().mul(x.c1())));let i=qi(n)?;Some(WideExact::new(x.c0().mul(i),x.c1().neg().mul(i)))}
fn word(b:&[u8])->Option<M31>{let v=(b[0] as u32)|((b[1] as u32)<<8)|((b[2] as u32)<<16)|((b[3] as u32)<<24);if v<P{Some(M31(v))}else{None}}
fn pair(b:&[u8])->Option<CM31>{let a=word(&b[0..4])?;let b=word(&b[4..8])?;Some(CM31::new(a,b))}
fn parse(b:&[u8])->Option<QM31>{let c0=pair(&b[0..8])?;let c1=pair(&b[8..16])?;Some(QM31{c0,c1})}
#[test]fn parsed_bytes(){std::panic::set_hook(Box::new(|_|{}));let mut n=0;for len in 0..=24 {for seed in 0..=255u8 {let mut b=[0;24];for i in 0..24{b[i]=seed.wrapping_add(i as u8);}let a=std::panic::catch_unwind(||QM31::from_le_bytes(&b[..len]));let c=std::panic::catch_unwind(||parse(&b[..len]));assert_eq!(a.is_err(),c.is_err());if let (Ok(a),Ok(c))=(a,c){assert_eq!(a,c);}n+=1;}}for limb in 0..4{for x in [0,P-1,P,P+1,u32::MAX]{let mut b=[0;16];for k in 0..4{b[limb*4+k]=(x>>(8*k))as u8;}assert_eq!(QM31::from_le_bytes(&b),parse(&b));n+=1;}}println!("V197 {n} paired parser cases including short-input panic/None/Some and every limb boundary; finite validation");}
#[test]fn inverses(){let mut n=0;for i in 0..=1024u32{for s in [i,i.wrapping_mul(0x1234567),u32::MAX-i]{let x=q(s);let w=WideExact::new(x,q(s.rotate_left(13)));assert_eq!(<QM31 as CodeField>::try_inv(x),qi(x));assert_eq!(<WideExact as CodeField>::try_inv(w),wi(w));n+=1;}}println!("V212/V213 {n} paired cases each; zero and raw carriers included; finite validation");}
#[test]fn points(){let mut n=0;for s in 0..256u32{let z=std::array::from_fn(|i|q(s.wrapping_mul(0x1234567).wrapping_add(i as u32)));let mut successor=z;let mut carry=QM31::ONE;let mut i=10;while i>0{i-=1;let bc=z[i].mul(carry);successor[i]=z[i].add(carry).sub(bc.add(bc));carry=bc;}let mut absorption=z;absorption[7]=QM31::ONE.sub(z[7]);absorption[6]=QM31::ONE.sub(z[6]);assert_eq!(aspis_core::state_only_prefix::r0::statement_points(&z),[z,successor,absorption]);n+=1;}println!("V218 {n} same-input points with every changed output retained; finite validation");}
#[test]fn contexts(){use aspis_core::state_only_hiding::StateOnlyHidingContext as C;let a=C::pinned([17;32],[93;32]);for k in 0..66{let mut b=a;if k<32{b.statement_digest[k]^=1;}else if k<64{b.mask_nonce[k-32]^=1;}else if k==64{b.mask_layout_fingerprint^=1;}else{b.layout_factor_fingerprint^=1;}let reference=|x:&C,y:&C|{let mut e=x.mask_layout_fingerprint==y.mask_layout_fingerprint&&x.layout_factor_fingerprint==y.layout_factor_fingerprint;for i in 0..32{e &= x.statement_digest[i]==y.statement_digest[i];e &= x.mask_nonce[i]==y.mask_nonce[i];}e};assert_eq!(a==b,reference(&a,&b));assert_eq!(a==a,reference(&a,&a));}println!("V216132 paired context comparisons, every field/byte; finite validation");}
#[test]fn takes(){for n in 0..64{let mut v:Vec<M31>=(0..n).map(|i|M31(i)).collect();let p=v.as_ptr();let old=std::mem::take(&mut v);assert_eq!(old.as_ptr(),p);assert_eq!(old.len(),n as usize);assert_eq!((v.len(),v.capacity()),(0,0));let mut v:Vec<QM31>=(0..n).map(q).collect();let p=v.as_ptr();let old=std::mem::take(&mut v);assert_eq!(old.as_ptr(),p);assert_eq!(old.len(),n as usize);assert_eq!((v.len(),v.capacity()),(0,0));}for n in [10,16]{let mut a:Vec<Vec<M31>>=(0..n).map(|i|vec![M31(i)]).collect();if n==10{let mut x:[Vec<M31>;10]=a.drain(..).collect::<Vec<_>>().try_into().unwrap();let old=std::mem::take(&mut x);for i in 0..10{assert_eq!(old[i],vec![M31(i as u32)]);assert_eq!((x[i].len(),x[i].capacity()),(0,0));}}else{let mut x:[Vec<M31>;16]=a.drain(..).collect::<Vec<_>>().try_into().unwrap();let old=std::mem::take(&mut x);for i in 0..16{assert_eq!(old[i],vec![M31(i as u32)]);assert_eq!((x[i].len(),x[i].capacity()),(0,0));}}}println!("V169128 Vec and two array-of-Vec takes at the emitted types; retained pointers/values and empty default capacities; finite validation");}
#[test]fn statements(){
 use aspis_statement::{pool_v1::{pair_tree_profile::{PoolV1PairLiveSnapshotV1 as Live,PoolV1PairLatePublicStatementV1 as St,POOL_V1_PAIR_TREE_DEPTH as D},PoolV1PairVerifiedAfterstateV1 as After},poseidon2::Digest};
 fn deq(a:&Digest,b:&Digest)->bool{let mut e=true;for i in 0..8{e &= a[i].0==b[i].0;}e}
 fn eq(a:&St,b:&St)->bool{let x=&a.live_snapshot;let y=&b.live_snapshot;let u=&a.candidate_afterstate;let v=&b.candidate_afterstate;let mut e=x.sequence==y.sequence&&x.next_pair_index==y.next_pair_index&&u.next_pair_index==v.next_pair_index;for i in 0..32{e &= x.pool[i]==y.pool[i];e &= x.deployment_domain[i]==y.deployment_domain[i];}e &= deq(&x.current_root,&y.current_root);e &= deq(&u.next_root,&v.next_root);for i in 0..D{e &= deq(&x.frontier[i],&y.frontier[i]);e &= deq(&u.next_frontier[i],&v.next_frontier[i]);}e}
 let a=St{live_snapshot:Live{pool:[17;32],deployment_domain:[93;32],sequence:7,next_pair_index:4,current_root:[M31(u32::MAX);8],frontier:[[M31(P);8];D]},candidate_afterstate:After{next_pair_index:5,next_root:[M31(P+1);8],next_frontier:[[M31(P-1);8];D]}};
 let total=64+3+16+2*D*8;for k in 0..total{let mut b=a;if k<32{b.live_snapshot.pool[k]^=1;}else if k<64{b.live_snapshot.deployment_domain[k-32]^=1;}else if k==64{b.live_snapshot.sequence^=1;}else if k==65{b.live_snapshot.next_pair_index^=1;}else if k==66{b.candidate_afterstate.next_pair_index^=1;}else if k<75{b.live_snapshot.current_root[k-67].0^=1;}else if k<83{b.candidate_afterstate.next_root[k-75].0^=1;}else{let i=k-83;if i<D*8{b.live_snapshot.frontier[i/8][i%8].0^=1;}else{let i=i-D*8;b.candidate_afterstate.next_frontier[i/8][i%8].0^=1;}}assert_eq!(a==b,eq(&a,&b));assert_eq!(a==a,eq(&a,&a));}println!("V246 {} paired statement comparisons, every nested field/byte/limb, raw noncanonical values retained; finite validation",2*total);
}
